<?php endforeach;?></pre></div></div><?php if($owner):?><form method="post" action="<?= $url ?>" style="margin-top:16px"><?= Csrf::field() ?><input type="hidden" name="action" value="history-restore"><input type="hidden" name="section" value="history"><input type="hidden" name="revision" value="<?= View::e($restore_preview['revision']) ?>"><input type="hidden" name="current_hash" value="<?= View::e($restore_preview['current_hash']) ?>"><div class="field"><label>現在のパスワード（ログイン直後は省略可）</label><input type="password" name="password" autocomplete="current-password"></div><button class="btn p">この公開設定に戻す</button></form><?php endif;?><?php endif;?>
